#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "dBW".parse::<PowerRatioUnit>(),
        Ok(PowerRatioUnit::DecibelWatt)
    );
    assert_eq!(
        format!("2.5 {}", "dBW").parse::<PowerRatio>(),
        Ok(PowerRatio::new(2.5, PowerRatioUnit::DecibelWatt))
    );
    assert_eq!(
        "dBmW".parse::<PowerRatioUnit>(),
        Ok(PowerRatioUnit::DecibelMilliwatt)
    );
    assert_eq!(
        format!("2.5 {}", "dBmW").parse::<PowerRatio>(),
        Ok(PowerRatio::new(2.5, PowerRatioUnit::DecibelMilliwatt))
    );
    assert_eq!(
        "dBm".parse::<PowerRatioUnit>(),
        Ok(PowerRatioUnit::DecibelMilliwatt)
    );
    assert_eq!(
        format!("2.5 {}", "dBm").parse::<PowerRatio>(),
        Ok(PowerRatio::new(2.5, PowerRatioUnit::DecibelMilliwatt))
    );
    assert_eq!(
        "1 not-a-unit".parse::<PowerRatio>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = PowerRatio::from_base(6.0);
    let b = PowerRatio::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = PowerRatio::<i64>::from_base(7);
    let b = PowerRatio::<i64>::from_base(2);
    assert_eq!(a + b, PowerRatio::from_base(9));
    assert_eq!(a % b, PowerRatio::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!(
        [a, b].iter().sum::<PowerRatio<i64>>(),
        PowerRatio::from_base(9)
    );
}
